#include "CadDocument.h"
#include "SketchGeometry.h"
#include "RectangularBodyPattern.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <BRepGProp.hxx>
#include <BRepAdaptor_Curve.hxx>
#include <GProp_GProps.hxx>
#include <iostream>
#include <limits>
namespace {
void check(bool b,const QString& m){if(!b)throw std::runtime_error(m.toStdString());}
gp_Pnt centroid(const EvaluatedBody& b){GProp_GProps p;BRepGProp::VolumeProperties(b.shape,p);return p.CentreOfMass();}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument d;auto sketch=SketchGeometry::newFeature(d.activeOwnerId(),"XY","Asymmetric seed");sketch=SketchGeometry::addRectangle(sketch,{{"u1Mm",0},{"v1Mm",0},{"u2Mm",12},{"v2Mm",3}});check(d.commit(SketchGeometry::replaceFeature(d.authored(),sketch),"Sketch").isEmpty(),"sketch");check(d.commit(CadDocument::extrusionCandidate(d.authored(),{{"sketchId",sketch["id"]},{"profileId",d.sketches()[0].profiles[0].profileId},{"distanceMm",7}}),"Seed").isEmpty(),"solid");
 const auto seed=d.bodies()[0];QString x,y;for(const auto& edge:seed.solidEdges){if(edge.edge.IsNull())continue;BRepAdaptor_Curve curve(edge.edge);if(curve.GetType()!=GeomAbs_Line)continue;const auto a=curve.Value(curve.FirstParameter()),b=curve.Value(curve.LastParameter());if(std::abs(a.X()-b.X())>1)x=edge.edgeId;else if(std::abs(a.Y()-b.Y())>1)y=edge.edgeId;}check(!x.isEmpty()&&!y.isEmpty(),"retained directions");
 auto axes=QJsonArray{QJsonObject{{"edgeId",x},{"quantity",3},{"spacingMm",20}}};QJsonObject args{{"sourceBodyId",seed.bodyId},{"axes",axes}};const auto initial=d.authored();auto candidate=CadDocument::patternCandidate(initial,args);check(CadDocument::evaluateCandidate(candidate).ok&&d.authored()==initial,"nonmutating preview");check(d.commit(candidate,"Row").isEmpty(),"row commit");const auto f=d.authored()["features"].toArray().last().toObject();const auto row=d.authored();check(f["type"]=="rectangularBodyPattern"&&d.bodies().size()==3,"separate authored type and row count");check(d.bodies()[0].summary==seed.summary&&d.bodies()[0].featureId==seed.featureId,"seed unchanged");const auto oldId=d.bodies()[2].bodyId;args["featureId"]=f["id"];axes[0]=QJsonObject{{"edgeId",x},{"quantity",4},{"spacingMm",25}};axes.append(QJsonObject{{"edgeId",y},{"quantity",2},{"spacingMm",15}});args["axes"]=axes;check(d.commit(CadDocument::patternCandidate(d.authored(),args),"Grid").isEmpty(),"grid edit");check(d.bodies().size()==8&&d.bodies()[2].bodyId==oldId,"grid stable coordinate identities");
 const auto c=centroid(seed);for(const auto& body:d.bodies()){check(body.summary["valid"].toBool(),"valid exact body");check(std::abs(body.summary["volumeMm3"].toDouble()-252)<1e-6,"equal actual volumes");if(body.bodyId==seed.bodyId)continue;const auto meta=body.summary["rectangularBodyPattern"].toObject();const auto t=meta["translationMm"].toArray();check(centroid(body).Distance(c.Translated(gp_Vec(t[0].toDouble(),t[1].toDouble(),t[2].toDouble())))<1e-6,"exact centroid placement");check(!body.supportFaces.empty()&&!body.solidEdges.empty()&&body.solidEdges[0].edgeId!=seed.solidEdges[0].edgeId,"independent topology identities");}
 const auto grid=d.authored();const auto j1=d.bodies()[4].bodyId;auto extended=args;auto larger=axes;auto axis0=larger[0].toObject();axis0["quantity"]=5;larger[0]=axis0;extended["axes"]=larger;check(d.commit(CadDocument::patternCandidate(d.authored(),extended),"Extend first direction").isEmpty()&&d.bodies()[5].bodyId==j1,"second row IDs survive first-direction count extension");d.history().undo();check(d.authored()==grid,"extension undo");d.history().undo();check(d.authored()==row&&d.bodies().size()==3,"edit undo");d.history().redo();check(d.authored()==grid,"edit redo");QTemporaryDir temp;check(d.save(temp.filePath("grid.alloy")).isEmpty(),"save");CadDocument reopened;check(reopened.open(temp.filePath("grid.alloy")).isEmpty()&&reopened.authored()==grid&&reopened.bodies().size()==8,"reopen");
 for(const double bad:{0.,-1.,2.5,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){auto a=axes;a[0]=QJsonObject{{"edgeId",x},{"quantity",bad==2.5?bad:4},{"spacingMm",bad==2.5?25:bad}};auto invalid=args;invalid["axes"]=a;bool refused=false;try{auto next=CadDocument::patternCandidate(d.authored(),invalid);refused=!d.commit(next,"Invalid").isEmpty();}catch(const std::exception&){refused=true;}check(refused&&d.authored()==grid,"atomic invalid input");}
 auto invalid=args;invalid["axes"]=QJsonArray{axes[0],axes[0]};check(!d.commit(CadDocument::patternCandidate(d.authored(),invalid),"Parallel").isEmpty()&&d.authored()==grid,"parallel refusal atomic");invalid["axes"]=QJsonArray{QJsonObject{{"edgeId",CadDocument::newId()},{"quantity",3},{"spacingMm",10}}};check(!d.commit(CadDocument::patternCandidate(d.authored(),invalid),"Missing").isEmpty()&&d.authored()==grid,"missing edge refusal");
 auto sourceEdit=CadDocument::extrusionCandidate(d.authored(),{{"featureId",seed.featureId},{"sketchId",sketch["id"]},{"profileId",d.sketches()[0].profiles[0].profileId},{"distanceMm",9}});check(d.commit(sourceEdit,"Source height").isEmpty(),"source recompute");for(const auto& b:d.bodies())check(std::abs(b.summary["volumeMm3"].toDouble()-324)<1e-6,"all copies follow source");
 const auto generated=d.bodies()[2];check(d.commit(CadDocument::moveCandidate(d.authored(),{{"targetBodyId",generated.bodyId},{"xMm",0},{"yMm",0},{"zMm",5}}),"Independent copy move").isEmpty(),"generated body downstream selection");const auto downstream=d.authored();invalid=args;invalid["axes"]=QJsonArray{QJsonObject{{"edgeId",x},{"quantity",2},{"spacingMm",25}}};check(!d.commit(CadDocument::patternCandidate(d.authored(),invalid),"Remove referenced").isEmpty()&&d.authored()==downstream,"removed generated references atomic");
 auto owned=CadDocument::componentCandidate(d.authored(),"Other owner");auto ownedArgs=QJsonObject{{"ownerId",owned["components"].toArray().last().toObject()["id"]},{"sourceBodyId",seed.bodyId},{"axes",axes}};check(!d.commit(CadDocument::patternCandidate(owned,ownedArgs),"Nonroot pattern").isEmpty()&&d.authored()==downstream,"nonroot pattern ownership refuses atomically");
 CadDocument oblique;auto triangle=SketchGeometry::newFeature(oblique.activeOwnerId(),"XY","Oblique directions");for(const auto coords:{QJsonArray{0,0,10,0},QJsonArray{10,0,4,6},QJsonArray{4,6,0,0}}){const auto added=SketchGeometry::addPointerEntity(triangle,"line",{{"u1Mm",coords[0]},{"v1Mm",coords[1]},{"u2Mm",coords[2]},{"v2Mm",coords[3]}});check(added.ok,added.error);triangle=added.feature;}
 check(oblique.commit(SketchGeometry::replaceFeature(oblique.authored(),triangle),"Triangle").isEmpty(),"triangle sketch");check(oblique.commit(CadDocument::extrusionCandidate(oblique.authored(),{{"sketchId",triangle["id"]},{"profileId",oblique.sketches()[0].profiles[0].profileId},{"distanceMm",5}}),"Triangle solid").isEmpty(),"triangle solid");const auto tri=oblique.bodies()[0];QString first,second;gp_Vec d1,d2;
 for(const auto& e:tri.solidEdges){if(e.edge.IsNull())continue;BRepAdaptor_Curve c(e.edge);if(c.GetType()!=GeomAbs_Line)continue;gp_Vec v(c.Value(c.FirstParameter()),c.Value(c.LastParameter()));if(std::abs(v.Z())>1e-6)continue;v.Normalize();if(first.isEmpty()){first=e.edgeId;d1=v;}else if(std::abs(v.Dot(d1))>1e-4&&v.Crossed(d1).Magnitude()>1e-4){second=e.edgeId;d2=v;break;}}
 check(!second.isEmpty(),"oblique pair");check(oblique.commit(CadDocument::patternCandidate(oblique.authored(),{{"sourceBodyId",tri.bodyId},{"axes",QJsonArray{QJsonObject{{"edgeId",first},{"quantity",2},{"spacingMm",20}},QJsonObject{{"edgeId",second},{"quantity",2},{"spacingMm",30}}}}}),"Oblique grid").isEmpty(),"nonparallel oblique accepted");check(oblique.bodies().size()==4,"oblique count");check(centroid(oblique.bodies()[3]).Distance(centroid(tri).Translated(d1*20+d2*30))<1e-6,"oblique independent vector-sum centroid");
 std::cout<<"rectangular body row/grid/coordinate IDs/seed/source/history/storage/refusals passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
